    ('佛天', '불천', '부처. 불타(佛陀).', '2026-11-21T23:30:27.927220Z'::timestamptz),
    ('佛勅', '불칙', '부처의 말씀.', '2026-11-21T23:30:27.927220Z'::timestamptz),
    ('佛陀', '불타', '범어(梵語) Buddha의 음역으로, 각자(覺者)라 번역함. 부처. 석가(釋迦). 부도(浮屠).', '2026-11-21T23:30:27.927220Z'::timestamptz),
